WorkflowProcessEvent.eventDescription:
function afterProcessCreate(processId) {
    log.info(
        ">>> [IRHO-LEADS] afterProcessCreate"
        + " | Solicitação criada: "
        + processId
    );
}

var BTS_ATIVIDADE_INICIO = 6;
var BTS_ATIVIDADE_TENTATIVA_CONTATO = 4;
var BTS_ATIVIDADE_OPORTUNIDADE_GERADA = 19;
var BTS_ATIVIDADE_PROPOSTA_COMERCIAL = 21;
var BTS_TABELA_HISTORICO_PERDAS = "tbHistoricoPerdas";

function beforeTaskSave(
    colleagueId,
    nextSequenceId,
    userList
) {
    var numSolicitacao = getValue("WKNumProces");
    var atividadeAtual = parseInt(
        getValue("WKNumState"),
        10
    );
    var completandoAtividade = btsTarefaEstaSendoConcluida();
    var acaoFluxo = btsTexto(
        hAPI.getCardValue("acao_fluxo_comercial")
    );
    var prefixoLog = ">>> [IRHO-LEADS] beforeTaskSave";

    log.info(
        prefixoLog
        + " | Solicitação: "
        + numSolicitacao
        + " | Atividade atual: "
        + atividadeAtual
        + " | Destino: "
        + nextSequenceId
        + " | Completando: "
        + completandoAtividade
        + " | Ação comercial: "
        + acaoFluxo
    );

    if (
        atividadeAtual == 0
        || atividadeAtual == BTS_ATIVIDADE_INICIO
    ) {
        if (completandoAtividade) {
            hAPI.setCardValue("acao_atividade", "MOVIMENTAR");
            hAPI.setCardValue(
                "acao_fluxo_comercial",
                "AVANCAR"
            );
        }

        return;
    }

    if (!btsEhAtividadeComercial(atividadeAtual)) {
        return;
    }

    if (!completandoAtividade) {
        hAPI.setCardValue("acao_atividade", "SALVAR");
        hAPI.setCardValue("acao_fluxo_comercial", "");
        return;
    }

    hAPI.setCardValue("acao_atividade", "MOVIMENTAR");

    if (acaoFluxo == "LEAD_PERDIDO") {
        btsRegistrarHistoricoPerda(atividadeAtual);
        hAPI.setCardValue("atividade_recuperacao", "");
        return;
    }

    hAPI.setCardValue(
        "acao_fluxo_comercial",
        "AVANCAR"
    );
}

function btsRegistrarHistoricoPerda(atividadeAtual) {
    var chavePendente = btsTexto(
        hAPI.getCardValue("perda_chave_pendente")
    );

    if (chavePendente == "") {
        throw "A chave de controle da perda não foi informada.";
    }

    var resumo = btsResumoHistorico(chavePendente);

    if (resumo.jaExiste) {
        log.info(
            ">>> [IRHO-LEADS] Histórico de perda já registrado"
            + " | Chave: "
            + chavePendente
        );
        return;
    }

    var filho = new java.util.HashMap();
    var formato = new java.text.SimpleDateFormat(
        "dd/MM/yyyy HH:mm"
    );

    filho.put("perda_id", chavePendente);
    filho.put("perda_ordem", String(resumo.maiorOrdem + 1));
    filho.put(
        "perda_data_hora",
        formato.format(new java.util.Date())
    );
    filho.put(
        "perda_atividade_codigo",
        String(atividadeAtual)
    );
    filho.put(
        "perda_atividade_nome",
        btsTexto(hAPI.getCardValue("atividade_origem_nome"))
    );
    filho.put(
        "perda_funil",
        btsTexto(hAPI.getCardValue("funil_origem_perda"))
    );
    filho.put(
        "perda_motivo_codigo",
        btsTexto(hAPI.getCardValue("motivo_perda_codigo"))
    );
    filho.put(
        "perda_motivo_texto",
        btsTexto(hAPI.getCardValue("motivo_perda_texto"))
    );

    hAPI.addCardChild(
        BTS_TABELA_HISTORICO_PERDAS,
        filho
    );
}

function btsResumoHistorico(chavePendente) {
    var indices = hAPI.getChildrenIndexes(
        BTS_TABELA_HISTORICO_PERDAS
    );
    var resultado = {
        jaExiste: false,
        maiorOrdem: 0
    };

    if (indices == null) {
        return resultado;
    }

    for (var i = 0; i < indices.length; i++) {
        var indice = String(indices[i]);
        var perdaId = btsTexto(
            hAPI.getCardValue("perda_id___" + indice)
        );
        var ordem = parseInt(
            hAPI.getCardValue("perda_ordem___" + indice),
            10
        );

        if (perdaId == chavePendente) {
            resultado.jaExiste = true;
        }

        if (!isNaN(ordem) && ordem > resultado.maiorOrdem) {
            resultado.maiorOrdem = ordem;
        }
    }

    return resultado;
}

function btsEhAtividadeComercial(atividadeAtual) {
    return atividadeAtual == BTS_ATIVIDADE_TENTATIVA_CONTATO
        || atividadeAtual == BTS_ATIVIDADE_OPORTUNIDADE_GERADA
        || atividadeAtual == BTS_ATIVIDADE_PROPOSTA_COMERCIAL;
}

function btsTarefaEstaSendoConcluida() {
    var valor = getValue("WKCompletTask");

    return valor === true
        || String(valor).toLowerCase() == "true";
}

function btsTexto(valor) {
    if (valor == null) {
        return "";
    }

    return String(valor).replace(/^\s+|\s+$/g, "");
}

var ATS_ATIVIDADE_TENTATIVA_CONTATO = 4;
var ATS_ATIVIDADE_OPORTUNIDADE_GERADA = 19;
var ATS_ATIVIDADE_PROPOSTA_COMERCIAL = 21;
var ATS_TABELA_TENTATIVAS = "tbTentativasContato";

function afterTaskSave(colleagueId, nextSequenceId, userList) {
    var numSolicitacao = getValue("WKNumProces");
    var atividadeAtual = parseInt(getValue("WKNumState"), 10);
    var completandoAtividade = atsTarefaEstaSendoConcluida();
    var acaoFluxo = atsTexto(
        hAPI.getCardValue("acao_fluxo_comercial")
    );
    var perdendoLead = acaoFluxo == "LEAD_PERDIDO";
    var prefixoLog = ">>> [IRHO-LEADS] afterTaskSave";

    log.info(
        prefixoLog
        + " | Solicitação: "
        + numSolicitacao
        + " | Atividade atual: "
        + atividadeAtual
        + " | Destino: "
        + nextSequenceId
        + " | Completando: "
        + completandoAtividade
        + " | Ação comercial: "
        + acaoFluxo
    );

    try {
        if (atividadeAtual == ATS_ATIVIDADE_TENTATIVA_CONTATO) {
            atsAtualizarResumoContato(
                numSolicitacao,
                completandoAtividade,
                perdendoLead,
                prefixoLog
            );
        } else if (
            completandoAtividade
            && perdendoLead
            && atsEhAtividadeComercial(atividadeAtual)
        ) {
            hAPI.setCardValue("status_lead", "PERDIDO");
        }

        if (
            completandoAtividade
            && perdendoLead
            && atsEhAtividadeComercial(atividadeAtual)
        ) {
            atsLimparCamposPendentes();
        }
    } catch (e) {
        log.error(
            prefixoLog
            + " | Erro ao atualizar a solicitação "
            + numSolicitacao
            + ": "
            + e
        );

        throw e;
    }
}

function atsAtualizarResumoContato(
    numSolicitacao,
    completandoAtividade,
    perdendoLead,
    prefixoLog
) {
    var dataHoraAtual = atsFormatarDataHoraAtual();

    hAPI.setCardValue(
        "atividade_atual",
        String(ATS_ATIVIDADE_TENTATIVA_CONTATO)
    );

    if (atsTexto(hAPI.getCardValue("numero_solicitacao")) == "") {
        hAPI.setCardValue(
            "numero_solicitacao",
            String(numSolicitacao)
        );
    }

    if (atsTexto(hAPI.getCardValue("data_inicio_contato")) == "") {
        hAPI.setCardValue(
            "data_inicio_contato",
            dataHoraAtual
        );
    }

    var resumo = atsCalcularResumoTentativas();

    hAPI.setCardValue(
        "total_tentativas",
        String(resumo.total)
    );
    hAPI.setCardValue(
        "ultima_tent_data",
        resumo.ultimaData
    );
    hAPI.setCardValue(
        "ultima_tent_meio",
        resumo.ultimoMeio
    );
    hAPI.setCardValue(
        "acao_atividade",
        completandoAtividade ? "MOVIMENTAR" : "SALVAR"
    );

    if (completandoAtividade && perdendoLead) {
        hAPI.setCardValue("status_lead", "PERDIDO");
    } else if (completandoAtividade) {
        hAPI.setCardValue(
            "status_lead",
            "CONTATO_FINALIZADO"
        );
    } else {
        hAPI.setCardValue("status_lead", "EM_CONTATO");
    }

    if (
        completandoAtividade
        && atsTexto(hAPI.getCardValue("data_fim_contato")) == ""
    ) {
        hAPI.setCardValue(
            "data_fim_contato",
            atsFormatarDataHoraAtual()
        );
    }

    log.info(
        prefixoLog
        + " | Resumo atualizado. Total: "
        + resumo.total
        + " | Último meio: "
        + resumo.ultimoMeio
        + " | Última data: "
        + resumo.ultimaData
    );
}

function atsCalcularResumoTentativas() {
    var indices = atsObterIndicesTentativas();
    var ultimaOrdem = -1;
    var ultimaData = "";
    var ultimoMeio = "";

    for (var i = 0; i < indices.length; i++) {
        var indice = indices[i];
        var ordem = parseInt(
            hAPI.getCardValue("tent_ordem___" + indice),
            10
        );

        if (isNaN(ordem)) {
            ordem = i + 1;
        }

        if (ordem >= ultimaOrdem) {
            ultimaOrdem = ordem;
            ultimaData = atsTexto(
                hAPI.getCardValue("tent_data___" + indice)
            );
            ultimoMeio = atsTexto(
                hAPI.getCardValue("tent_meio___" + indice)
            );
        }
    }

    return {
        total: indices.length,
        ultimaData: ultimaData,
        ultimoMeio: ultimoMeio
    };
}

function atsObterIndicesTentativas() {
    var resultado = [];
    var indices = hAPI.getChildrenIndexes(
        ATS_TABELA_TENTATIVAS
    );

    if (indices == null) {
        return resultado;
    }

    for (var i = 0; i < indices.length; i++) {
        resultado.push(String(indices[i]));
    }

    return resultado;
}

function atsLimparCamposPendentes() {
    hAPI.setCardValue("motivo_perda_codigo", "");
    hAPI.setCardValue("motivo_perda_texto", "");
    hAPI.setCardValue("perda_chave_pendente", "");
}

function atsEhAtividadeComercial(atividadeAtual) {
    return atividadeAtual == ATS_ATIVIDADE_TENTATIVA_CONTATO
        || atividadeAtual == ATS_ATIVIDADE_OPORTUNIDADE_GERADA
        || atividadeAtual == ATS_ATIVIDADE_PROPOSTA_COMERCIAL;
}

function atsTarefaEstaSendoConcluida() {
    var valor = getValue("WKCompletTask");

    return valor === true
        || String(valor).toLowerCase() == "true";
}

function atsTexto(valor) {
    if (valor == null) {
        return "";
    }

    return String(valor).replace(/^\s+|\s+$/g, "");
}

function atsFormatarDataHoraAtual() {
    var formato = new java.text.SimpleDateFormat(
        "yyyy-MM-dd HH:mm:ss"
    );

    return formato.format(new java.util.Date());
}

function beforeStateEntry(sequenceId) {
    var numeroSolicitacao = getValue("WKNumProces");

    log.info(
        ">>> [IRHO-LEADS] beforeStateEntry"
        + " | Solicitação: "
        + numeroSolicitacao
        + " | Destino: "
        + sequenceId
    );
}

function afterTaskCreate(colleagueId) {
    var atividadeAtual = parseInt(getValue("WKNumState"), 10);
    var numeroSolicitacao = getValue("WKNumProces");

    log.info(
        ">>> [IRHO-LEADS] afterTaskCreate"
        + " | Solicitação: "
        + numeroSolicitacao
        + " | Atividade: "
        + atividadeAtual
        + " | Responsável: "
        + colleagueId
    );
}
